def add(out,origin,pages):
    e=html.escape
    def link(url,label,cls=''):
        return f'<a class="{cls}" href="{e(url,quote=True)}">{e(label)}</a>'
    def render(path,title,desc,body):
        write_editorial_page(out,origin,pages,path,title,desc,'<div class="wrap local-help-page">'+body+'</div>')
        target=out/path.strip('/')/'index.html'
        target.write_text(target.read_text().replace('</head>','<link rel="stylesheet" href="/assets/local-help.css"></head>'))
    def card(p):
        return '<article class="local-pro-card"><div class="local-monogram" aria-hidden="true">'+e(p['initials'])+'</div><span class="local-status">OWNER-RECOMMENDED</span><h3>'+link('/businesses/'+p['slug']+'/',p['name'])+'</h3><p>'+e(p['label'])+'</p><p>'+e(p['detail'])+'</p>'+link('/businesses/'+p['slug']+'/','Meet '+p['name']+' →')+'</article>'
    evidence='<p class="local-evidence">Recommended by Wazoozie’s owner. Public business details checked November 6, 2026 using the linked business sources. This records the recommendation and source check; it does not claim an independent license, insurance, certification or workmanship inspection. No rating, paid partnership or guaranteed outcome is implied.</p>'
    for p in PEOPLE:
        parent='/vehicle-wraps/' if p.get('vehiclewrap') else '/auto-mechanics/' if p['category']=='automotive' else '/real-estate-agents/'
        body='<div class="breadcrumb">'+link('/local-help/','Local help')+'<span>/</span>'+link(parent,'Vehicle wraps' if p.get('vehiclewrap') else 'Auto mechanics' if p['category']=='automotive' else 'Real estate agents')+'</div><section class="local-profile-hero"><div><span class="local-status">OWNER-RECOMMENDED · PUBLIC SOURCES LINKED</span><h1>'+e(p['name'])+'</h1><p class="local-lede">'+e(p['intro'])+'</p><p>'+e(p['label'])+'</p><p>'+e(p['detail'])+'</p><div class="local-actions">'+(link('tel:'+p['tel'],'Call '+p['phone'],'btn primary') if p.get('tel') else '')+link(p['website'],p.get('website_label','Visit the official website ↗'),'btn outline')+'</div></div><div class="local-profile-mark" aria-hidden="true">'+e(p['initials'])+'</div></section><section class="local-profile-body"><div><h2>A useful first introduction.</h2><p>'+e(p['copy'])+'</p><h2>Three things to ask.</h2><ol>'+''.join('<li>'+e(q)+'</li>' for q in p['questions'])+'</ol><p>Contact goes directly to the listed business or professional. Wazoozie does not send this inquiry to Middletown HVAC or book an appointment here.</p></div><aside><h2>What this listing tells you.</h2>'+evidence+'<h3>Public sources</h3><ul>'+''.join('<li>'+link(url,label+' ↗')+'</li>' for label,url in p['sources'])+'</ul>'+('<p>'+link('https://www.pals.pa.gov/pages/search.html','Check Pennsylvania license records ↗')+'</p><p>A business profile is not a current license-status verification. Confirm the appropriate state and professional record directly.</p>' if p['category']=='realestate' else '')+'</aside></section>'
        render('/businesses/'+p['slug']+'/',p['name']+' | Local Referral',p['intro']+' Find public contact details, linked sources and questions for the first conversation.',body)
        # Mark up only identity and contact information actually shown on the page.
        target=out/'businesses'/p['slug']/'index.html';s=target.read_text()
        entity={'@context':'https://schema.org','@type':p.get('schema','AutoRepair' if p['category']=='automotive' else 'Person'),'name':p['name'],'url':(origin or 'http://localhost:8123')+'/businesses/'+p['slug']+'/','telephone':p['tel'],'sameAs':p['website']}
        if not p.get('phone'):entity.pop('telephone',None)
        s=s.replace('</head>','<script type="application/ld+json">'+json.dumps(entity).replace('<','\\u003c')+'</script></head>');target.write_text(s)
    mechanic=PEOPLE[0];agents=[p for p in PEOPLE if p['category']=='realestate'];wrap=next(p for p in PEOPLE if p.get('vehiclewrap'))
    auto='<div class="breadcrumb">'+link('/local-help/','Local help')+'<span>/</span>Auto mechanics</div><div class="local-intro"><div class="eyebrow">FOR WHAT GETS YOU THERE</div><h1>A good mechanic.<br><em>A clearer next step.</em></h1><p class="local-lede">Meet the local shops Wazoozie’s owner recommends. Start with your vehicle and the concern, then confirm the work and appointment directly.</p></div><div class="local-pro-grid">'+''.join(card(p) for p in PEOPLE if p['category']=='automotive' and not p.get('vehiclewrap'))+'</div><section class="local-question-band"><h2>Before the keys change hands.</h2><p>Describe the symptoms and ask what the diagnostic visit includes. Request a written estimate and agree how additional work will be approved. Keep the repair warranty with the final invoice.</p><p>'+link('https://consumer.ftc.gov/articles/0211-auto-repair-basics','Read the FTC’s auto-repair consumer guide ↗')+'</p></section><p>'+link('/for-contractors/?category=automotive#business-application','Own an auto shop? Apply for listing consideration →')+'</p>'
    auto += '<section class="local-question-band"><h2>Looking for a different kind of vehicle project?</h2><p>Meet Sound Wraps for vinyl and vehicle appearance work.</p>'+link('/vehicle-wraps/','Explore vehicle wraps →')+'</section>'
    render('/auto-mechanics/','Auto Mechanics & Repair | Local Referrals','Explore owner-recommended auto repair shops, linked public contact details and questions to ask before service.',auto)
    wraps='<div class="breadcrumb">'+link('/local-help/','Local help')+'<span>/</span>Vehicle wraps</div><div class="local-intro"><div class="eyebrow">A DIFFERENT KIND OF CURB APPEAL</div><h1>Your ride.<br><em>A little more you.</em></h1><p class="local-lede">Explore Sound Wraps for vinyl customization in West Chester. Discuss the finish, vehicle and exact surfaces before choosing materials.</p></div><div class="local-pro-grid">'+card(wrap)+'</div><section class="local-question-band"><h2>Know what the wrap includes.</h2><p>Ask about material, panel coverage, preparation, door jambs, existing film removal and care. Confirm the appointment location and written quote directly.</p>'+link('/pricing-guide/#vehicle-wraps','See sourced wrap-price references →')+'</section>'
    render('/vehicle-wraps/','Vehicle Wraps in West Chester | Sound Wraps','Meet Sound Wraps for full and partial vehicle wraps, trim and custom vinyl work in West Chester. Explore the business and request a direct quote.',wraps)
    real='<div class="breadcrumb">'+link('/local-help/','Local help')+'<span>/</span>Real estate agents</div><div class="local-intro"><div class="eyebrow">FOR THE NEXT CHAPTER</div><h1>A move starts<br><em>with a conversation.</em></h1><p class="local-lede">Meet the real estate professionals recommended by Wazoozie’s owner. Compare the people, ask about your plans and decide who you want to work with.</p></div><div class="local-pro-grid">'+''.join(card(p) for p in agents)+'</div><section class="local-question-band"><h2>The useful details, before a decision.</h2><p>Ask about the professional’s role, your property location, communication, proposed services and written terms. Public profile information is not an independent license-status check or a promise of a particular transaction result.</p><p>'+link('https://www.pals.pa.gov/pages/search.html','Look up Pennsylvania professional-license records ↗')+'</p></section><p>'+link('/for-contractors/?category=realestate#business-application','Work in real estate? Apply for consideration →')+'</p>'
    render('/real-estate-agents/','Local Real Estate Agents | Owner-Recommended Professionals','Meet Caitlin Kerezsi, Megan Kerezsi and Libbi Skivo through linked professional profiles and direct business contact details.',real)
    categories='<div class="local-category-grid"><a href="/#find"><span>01 / YOUR HOME</span><h2>Good help for the place you live.</h2><p>Heating, cooling, plumbing, electrical work, painting, carpentry and larger projects.</p><strong>Explore home services ↗</strong></a><a href="/auto-mechanics/"><span>02 / YOUR CAR</span><h2>A shop you can get to know.</h2><p>Explore owner-recommended auto repair and vehicle-wrap businesses.</p><strong>Explore automotive referrals ↗</strong></a><a href="/real-estate-agents/"><span>03 / YOUR NEXT CHAPTER</span><h2>The people behind the move.</h2><p>Meet recommended real estate professionals and discuss your plans directly.</p><strong>Explore real estate professionals ↗</strong></a></div>'
    overview='<div class="local-intro"><div class="eyebrow">YOUR LOCAL SHORTLIST. A LITTLE MORE OF LIFE.</div><h1>Small businesses.<br><em>Reputations worth protecting.</em></h1><p class="local-lede">The house. The car. The next move. We make room for small businesses and local affiliates with strong reputations. Read who recommended each new connection, check the linked evidence and talk directly with the people behind the work.</p></div>'+categories+'<section class="local-question-band"><h2>Local businesses we recommend.</h2><p>We built Wazoozie to make it easier to find good local help. These are businesses we recommend for your home, your car and your next move. Each profile has the details to help you decide who to call.</p>'+link('/our-standards/','Read the home-service directory standards →')+'</section><p>'+link('/for-contractors/','Introduce your local business →')+'</p>'
    render('/local-help/','Local Help | Home Services, Auto Mechanics & Real Estate','Find local home services, an owner-recommended automotive shop and real estate professionals, with direct contact details and linked sources.',overview)
    photo='<figure class="wrap-project-photo"><img src="/assets/sound-wraps-project.webp" width="960" height="1280" loading="lazy" alt="Vehicle project published by Sound Wraps on Facebook"><figcaption>Photo: Sound Wraps LLC, published September 9, 2026. <a href="https://www.facebook.com/photo/?fbid=1575250094402346">View the original public photo ↗</a></figcaption></figure>'
    for path in ('vehicle-wraps','businesses/sound-wraps-west-chester'):
        target=out/path/'index.html';target.write_text(target.read_text().replace('</main>',photo+'</main>',1))
    home=out/'index.html';s=home.read_text();teaser='<section class="wrap local-home-expansion" aria-labelledby="local-life-title"><div class="eyebrow">A LITTLE MORE OF LIFE, LOCALLY.</div><h2 id="local-life-title">The house. The car. The next chapter.</h2><p>One place to start with local recommendations and clear information.</p>'+categories+'</section>'
    s=s.replace('<section class="wrap journal-home"',teaser+'<section class="wrap journal-home"',1);home.write_text(s)
    for target in out.rglob('*.html'):
        s=target.read_text().replace('<a href="/#find">Find a pro</a>','<a href="/local-help/">Local help</a>')
        s=s.replace('<nav aria-label="Mobile navigation">','<nav aria-label="Mobile navigation"><a href="/local-help/">Explore local help</a>',1)
        s=s.replace('<strong>The useful details</strong>','<strong>The useful details</strong><a href="/local-help/">Home, auto &amp; real estate</a>',1)
        s=s.replace('</head>','<link rel="stylesheet" href="/assets/local-help.css"></head>',1) if target==home else s
        target.write_text(s)
    shutil.copy(out.parent/'assets/local-help.css',out/'assets/local-help.css')
    shutil.copy(out.parent/'assets/sound-wraps-project.webp',out/'assets/sound-wraps-project.webp')
